from lib import *
S = SS('j261')
steps = [
    step("完成回调运行在哪个线程(JDK 21):用 AsynchronousChannelGroup.withFixedThreadPool(2) 建一个线程组,accept 的回调运行在线程 aio-21,read 的回调运行在线程 aio-20——都是线程组里的线程,不是发起调用的 main 线程。回调里不能做阻塞操作,否则会占住线程组里仅有的几个线程。", t=tl(S(1)), done=lidx(S(1), 'accept 回调运行在线程'), mark=lidx(S(1), 'read 回调运行在线程'), kv=KV([['accept 回调', '线程 aio-21(线程组)'], ['read 回调', '线程 aio-20(线程组)'], ['发起调用的线程', 'main']], ['read 回调'])),
    step("数据已经就绪时,回调可以被“直接调用”(嵌套在 read 调用里)。对端先写入 5000 字节,服务端在回调里每次读 1 字节并再发起下一次读,共 5000 次回调,都在同一个线程 aio 上:默认下栈深度最小 11、最大 139,共 17 种深度(11、19、27……每深一层 8 帧),每种深度约 295 次——嵌套了 16 层后回到池线程重新调度。设置 -Dsun.nio.ch.maxCompletionHandlersOnStack=0 后所有回调的栈深度都是 11(1 种深度 × 5000 次);=64 时最大深度 523、共 65 种深度。(我先用了错的属性名 jdk.nio.ch.…,没有任何效果,正确的是 sun.nio.ch.…。)", t=tl(S(2)), done=lidx(S(2), '[默认]', '最小 11、最大 139'), mark=lidx(S(2), 'maxCompletionHandlersOnStack=0', 'maxCompletionHandlersOnStack=64', '最大 523'), b=bars([['默认:最大栈深度', 139, '139(17 种)'], ['=0:最大栈深度', 11, '11(1 种)'], ['=64:最大栈深度', 523, '523(65 种)']], 523, done=[0, 1, 2]), kv=KV([['默认', '直接调用嵌套 16 层,栈深度 11–139'], ['=0', '不嵌套,深度恒为 11'], ['=64', '嵌套 64 层,最大深度 523']], ['默认'])),
    step("同一个通道上的并发限制:已有一个 read 未完成时再调 read 抛 ReadPendingException;对端不读、连续发起 1 MiB 的 write 到第 7 个才在 50 ms 后仍未完成(此前每个都立即完成了),这时再调 write 抛 WritePendingException(write 只有在 socket 发送缓冲区满了才会处于未完成状态)。已连接的通道再 connect 抛 AlreadyConnectedException,未连接就 read 抛 NotYetConnectedException,用只读 ByteBuffer 作 read 的目标抛 IllegalArgumentException。每个通道同一时间只能有一个未完成的 read 和一个未完成的 write。", t=tl(S(3)), done=lidx(S(3), '已有一个 read 未完成时再调 read', '第一个 read 之后完成'), mark=lidx(S(3), '第 7 个 write', 'WritePendingException', 'AlreadyConnectedException', 'NotYetConnectedException', '只读 ByteBuffer'), kv=KV([['第二个未完成的 read', 'ReadPendingException'], ['第二个未完成的 write', 'WritePendingException'], ['只读 ByteBuffer 作 read 目标', 'IllegalArgumentException']], ['第二个未完成的 write'])),
    step("部分写:对端一直不读时,write(16 MiB 的 ByteBuffer) 第一次完成只写了 327,212 字节(319 KiB),缓冲区还剩 16,450,004 字节,耗时 2 ms;对端开始读之后,要连续调用 write 共 10 次才写完 16 MiB(16,777,216 字节)。write 的完成回调只说明写出了一部分,必须检查 hasRemaining() 并继续写。", t=tl(S(4)), done=lidx(S(4), '对端一直不读时'), mark=lidx(S(4), '对端开始读之后'), b=bars([['第一次 write 写出', 319, '319 KiB'], ['总共需要', 16384, '16 MiB(共 10 次 write)']], 16384, done=[0, 1]), kv=KV([['第一次 write 完成', '写了 327,212 字节,还剩 16,450,004'], ['写完 16 MiB', '共 10 次 write']], ['第一次 write 完成'])),
    step("读超时:read(300 ms 超时) 的 failed 回调收到 InterruptedByTimeoutException,用时 313 ms,回调线程是 Thread-12(默认线程组);超时之后再对同一个通道 read 抛 IllegalStateException,通道 isOpen 仍是 true。超时之后通道的读取状态不可再用,应该关闭这个通道。", t=tl(S(5)), done=lidx(S(5), 'read(300 ms 超时)'), mark=lidx(S(5), '超时之后再 read', 'isOpen = true'), kv=KV([['超时回调', 'InterruptedByTimeoutException,313 ms'], ['超时之后再 read', 'IllegalStateException'], ['超时之后', '通道 isOpen = true,但不能再读']], ['超时之后再 read'])),
    step("回调抛异常与线程组关闭:accept 回调在 aio-1 线程里抛出 RuntimeException,默认 UncaughtExceptionHandler 收到(线程 aio-1),线程组新建了第 2 个线程,下一个 accept 的 Future 在 2 秒内正常完成。group.shutdown() 之后 isShutdown = true、isTerminated = false;关闭客户端通道与监听通道后 awaitTermination(1 s) 仍是 false,再关闭第二个服务端通道还是 false,直到最后关闭“抛异常的回调里拿到的那个”第一个服务端通道才 true(isTerminated = true)——accept 得到的每个通道都要关闭,线程组才会终止。", t=tl(S(6)), done=lidx(S(6), 'accept 回调在线程 aio-1', '默认 UncaughtExceptionHandler', 'ThreadFactory 一共创建了 2 个线程'), mark=lidx(S(6), 'group.shutdown() 之后', '关闭了客户端通道', '再关闭第二个', '最后关闭第一个'), kv=KV([['回调抛异常', 'UncaughtExceptionHandler 收到,线程被替换'], ['shutdown() 之后', '还有打开的通道就不会终止'], ['全部通道关闭后', 'awaitTermination = true']], ['shutdown() 之后'])),
]
A = mkartj('j261', 261, 'Java,NIO.2,AsynchronousSocketChannel,异步IO,CompletionHandler,真实验证,动画演示',
    '在 JDK 21 上实测 AsynchronousSocketChannel:完成回调运行在线程组的线程上;数据已就绪时回调会直接嵌套调用 16 层(sun.nio.ch.maxCompletionHandlersOnStack 默认值,设 0 后栈深度恒为 11);每个通道只能有一个未完成的 read 与 write;write 只写出 319 KiB 就完成;读超时之后通道不可再读;未关闭的 accept 通道会让线程组无法终止。',
    '异步 NIO 的“回调”不是随便在哪里运行的函数。这篇用真实的环回连接量出它在哪个线程上运行、栈有多深、同一个通道上有哪些并发限制、write 与超时的完成语义,以及线程组为什么不终止。',
    [('11–139 → 11', '默认下回调里的栈深度范围(直接调用嵌套 16 层);sun.nio.ch.maxCompletionHandlersOnStack=0 后恒为 11'), ('319 KiB / 16 MiB', '对端不读时,write 一个 16 MiB 的 ByteBuffer 第一次完成写出的字节数'), ('2 个', 'accept 得到的服务端通道:两个都关闭后线程组才终止(只关闭其中一个时 awaitTermination 仍是 false)')],
    [('回调线程', None), ('直接调用与栈深度', None), ('并发限制', None), ('部分写', None), ('读超时', None), ('回调异常与线程组', None)],
    steps, [ENV_J + '。JDK 21.0.12,环回 127.0.0.1:9741;每个场景一个新 JVM', '没有验证:AsynchronousFileChannel、多个客户端的并发负载与吞吐(与 NIO Selector 的对比)、Linux(epoll)与 Windows(IOCP)上的差异(这里是 macOS 的 kqueue 实现)、TLS(AsynchronousSocketChannel 本身不支持)、背压与缓冲区管理策略'], 'AsynchronousSocketChannel')
